double bsPrice(double S, double K, double T, double r, double v, bool call) {
    auto N = [](double x) { return 0.5 * (1 + erf(x / sqrt(2.0))); };
    double d1 = (log(S / K) + (r + v * v / 2) * T) / (v * sqrt(T)), d2 = d1 - v * sqrt(T);
    return call ? S * N(d1) - K * exp(-r * T) * N(d2) : K * exp(-r * T) * N(-d2) - S * N(-d1);
}
